// === Tab: mySketch.js ===
// A fork of tp5_250806_StaircaseWaterway by はぅ君. I extended the code for clarity.

let particles = [];
let time = 0;
let W = 720;

function setup() {
	createCanvas(W, W);
}

function draw() {
  background(0, 9);
  filter(BLUR);
  stroke(255);
  for (let i = 9; i--;) {
    particles[time++ % (W * 9)] = {
      x: (time * 99) % W,
      y: 0,
      g: 0,
      s: 3
    };
  }

  particles.forEach(p => {
    strokeWeight(p.s *= 0.997);
    let Noise = noise(p.x / W, p.y / 9, time / W);

    if (Noise > 0.4) {
      p.x += 0;
    } else {
      p.x += (Noise % 0.1 > 0.05 ? 1 : -1) + (p.g = 0);
    }

    p.y += Noise > 0.4 ? (p.g += 0.5) : 0.5;
    point(p.x, p.y);
  });
}

